*{box-sizing:border-box} :root{--ink:#f4f4ed;--muted:#a3aaa9;--lime:#d5fa63;--dark:#10161a;--panel:rgba(14,20,24,.82)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#111820;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;overflow:hidden;background:#18242a}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(7,12,16,.47),transparent 58%),linear-gradient(0deg,rgba(7,12,16,.2),transparent 35%);z-index:1}.loading{position:absolute;z-index:10;inset:0;display:grid;place-content:center;justify-items:center;gap:15px;background:#111820;font:700 12px 'DM Sans';letter-spacing:.18em;color:#d5fa63;transition:opacity .4s}.loading.done{opacity:0;pointer-events:none}.spinner{width:24px;height:24px;border:2px solid #ffffff35;border-top-color:#d5fa63;border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.menu{position:absolute;inset:0;z-index:3;overflow:hidden;padding:32px 5.3vw 27px;background:linear-gradient(90deg,rgba(8,14,18,.75),rgba(8,14,18,.2) 53%,rgba(8,14,18,.08));transition:opacity .45s,visibility .45s}.menu.hidden{opacity:0;visibility:hidden;pointer-events:none}.menu-top,.menu-footer{display:flex;align-items:center;justify-content:space-between;position:relative;z-index:1}.brand-mark,.hud-brand{font:800 16px 'Barlow Condensed';letter-spacing:.06em}.brand-mark span,.hud-brand span{color:var(--lime)}.menu-location{font-size:10px;font-weight:700;letter-spacing:.15em;color:#d0d5d3}.menu-location i,.live-dot{display:inline-block;width:6px;height:6px;margin-right:8px;border-radius:50%;background:var(--lime);box-shadow:0 0 11px var(--lime)}.hero-copy{position:absolute;left:11.5vw;top:50%;transform:translateY(-46%);z-index:1}.eyebrow{display:flex;align-items:center;gap:9px;color:#d5fa63;font-size:10px;font-weight:700;letter-spacing:.19em}.eyebrow span{width:22px;height:1px;background:var(--lime)}h1,h2{font-family:'Barlow Condensed',sans-serif;font-weight:900;margin:16px 0 0;letter-spacing:-.03em}h1{font-size:clamp(72px,11vw,154px);line-height:.75;text-shadow:0 5px 35px #0005}h1 em,h2 em{font-style:normal;color:var(--lime)}.hero-copy p{font-size:14px;color:#d4d8d5;margin:24px 0 25px;letter-spacing:.01em}.start-button{height:54px;width:220px;background:var(--lime);border:0;color:#131a1b;display:flex;justify-content:space-between;align-items:center;padding:0 19px;font-size:11px;font-weight:800;letter-spacing:.13em;cursor:pointer;transition:transform .2s,background .2s}.start-button:hover{transform:translateY(-3px);background:#e2ff86}.start-button b{font-size:18px}.menu-hint{margin-top:15px;color:#e0e6e2;font-size:9px;font-weight:700;letter-spacing:.09em}.menu-hint span{color:#8e9997;padding:0 5px}.menu-footer{position:absolute;bottom:25px;left:5.3vw;right:5.3vw;color:#aab1af;font-size:8px;font-weight:700;letter-spacing:.13em}.menu-watermark{position:absolute;right:-2vw;bottom:8%;font:900 23vw/.7 'Barlow Condensed';color:#ffffff09;letter-spacing:-.08em;pointer-events:none}.hud{position:absolute;inset:0;z-index:2;pointer-events:none}.hud.hidden{display:none}.hud-top{position:absolute;top:27px;left:32px;right:32px;display:flex;align-items:center;gap:24px}.hud-location{font:700 10px 'DM Sans';letter-spacing:.14em}.hud-location small{display:block;color:#aeb6b4;font-size:8px;margin:4px 0 0 15px;letter-spacing:.2em}.icon-button{margin-left:auto;width:38px;height:38px;border:1px solid #ffffff50;background:#10171a80;font-size:24px;pointer-events:auto}.speed-card{position:absolute;right:5.2%;bottom:9.5%;width:195px;padding:13px 15px 11px;background:linear-gradient(120deg,rgba(10,16,19,.78),rgba(10,16,19,.38));border-left:2px solid var(--lime);backdrop-filter:blur(8px)}.speed-line{display:flex;align-items:baseline;gap:7px}.speed-line strong{font:800 54px/.9 'Barlow Condensed';letter-spacing:-.04em}.speed-line span{font-size:9px;font-weight:700;letter-spacing:.1em;color:#d5fa63}.speed-track{height:2px;background:#ffffff30;margin:9px 0 8px}.speed-track i{display:block;height:100%;width:0;background:var(--lime);transition:width .12s}.vehicle-name{font-size:8px;font-weight:700;letter-spacing:.16em;color:#c0c8c4}.mission-card{position:absolute;top:105px;left:32px;display:flex;gap:12px;padding:13px 17px 13px 13px;background:var(--panel);border-left:2px solid var(--lime);backdrop-filter:blur(7px)}.mission-icon{font-size:20px;color:var(--lime);padding:3px 4px}.mission-card small,.mission-card strong,.mission-card span{display:block}.mission-card small{font-size:8px;letter-spacing:.16em;color:var(--lime);font-weight:700}.mission-card strong{font-size:12px;margin:3px 0}.mission-card span{font-size:9px;color:#aeb7b4}.cash-card{position:absolute;right:32px;top:27px;text-align:right}.cash-card span{display:block;font-size:8px;color:#c6cecb;letter-spacing:.18em}.cash-card strong{font:700 18px 'Barlow Condensed';color:var(--lime)}.cash-card b{font:700 18px 'Barlow Condensed'}.controls-legend{position:absolute;bottom:27px;left:32px;display:flex;align-items:center;gap:5px;color:#d6dbd7;font-size:8px;letter-spacing:.1em}.controls-legend kbd,.shop-prompt kbd{font:700 8px 'DM Sans';padding:5px 6px;border:1px solid #ffffff70;background:#121b1d99;border-radius:3px;margin-left:4px}.controls-legend span{margin:0 8px 0 2px;color:#acb5b1}.shop-prompt{position:absolute;left:50%;bottom:22%;transform:translateX(-50%);padding:12px 16px;background:#101719dd;border:1px solid #d5fa63a8;color:#f1f3ea;font-size:9px;font-weight:700;letter-spacing:.12em;white-space:nowrap;animation:pulse 1.5s infinite}.shop-prompt.hidden{display:none}.shop-prompt>span{color:var(--lime);margin-right:7px}@keyframes pulse{50%{box-shadow:0 0 20px #d5fa6333}}.toast{position:absolute;top:28%;left:50%;transform:translate(-50%,-10px);padding:10px 17px;background:#12191be8;border-bottom:1px solid var(--lime);font-size:10px;letter-spacing:.1em;opacity:0;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.shop{position:absolute;z-index:5;inset:0;background:linear-gradient(120deg,rgba(9,14,17,.94),rgba(15,24,27,.88));padding:5vh 7vw;backdrop-filter:blur(15px);transition:opacity .25s}.shop.hidden{display:none}.shop-head{display:flex;justify-content:space-between;align-items:flex-start}.shop h2{font-size:clamp(44px,6vw,78px);line-height:.9;margin-top:8px}.shop-subtitle{margin:12px 0 24px;color:#bac2bf;font-size:13px}.close-button{background:transparent;border:1px solid #ffffff44;padding:9px 12px;color:#c4ceca;font-size:9px;font-weight:700;letter-spacing:.12em;cursor:pointer}.close-button b{font-size:19px;color:var(--lime);margin-left:10px;vertical-align:-2px}.vehicle-list{display:grid;grid-template-columns:repeat(3,minmax(170px,1fr));gap:13px;max-width:1000px}.vehicle-card{position:relative;min-height:235px;background:linear-gradient(145deg,#253237,#151e22);border:1px solid #ffffff1a;padding:17px;display:flex;flex-direction:column;justify-content:space-between;cursor:pointer;transition:.2s;overflow:hidden}.vehicle-card:hover,.vehicle-card.selected{border-color:var(--lime);transform:translateY(-3px)}.vehicle-card:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 68% 46%,#d5fa6314,transparent 58%);pointer-events:none}.vehicle-class{position:relative;color:var(--lime);font-size:8px;font-weight:700;letter-spacing:.18em}.vehicle-art{position:absolute;left:5%;right:5%;top:48px;height:105px;display:flex;align-items:center;justify-content:center}.vehicle-art canvas{width:100%;height:100%}.vehicle-info{position:relative;display:flex;justify-content:space-between;align-items:flex-end}.vehicle-info h3{margin:0;font:700 26px 'Barlow Condensed';letter-spacing:.01em}.vehicle-info p{margin:3px 0 0;color:#aab5b0;font-size:8px;letter-spacing:.1em}.vehicle-price{text-align:right;font:700 19px 'Barlow Condensed';color:var(--lime)}.vehicle-price small{display:block;color:#aab5b0;font:700 8px 'DM Sans';letter-spacing:.12em}.shop-foot{position:absolute;bottom:25px;left:7vw;right:7vw;display:flex;justify-content:space-between;color:#86918e;font-size:8px;font-weight:700;letter-spacing:.15em}.rotate-notice{display:none}.touch-controls{display:none;pointer-events:none}.touch-controls button{pointer-events:auto;user-select:none;-webkit-user-select:none;touch-action:none}.touch-left,.touch-right{position:absolute;bottom:30px;display:flex;gap:10px}.touch-left{left:18px}.touch-right{right:18px;align-items:flex-end}.touch-controls button{border:1px solid #ffffff55;background:#111b1dcc;border-radius:50%;width:55px;height:55px;font-weight:700;color:white}.touch-right button:nth-child(1){width:57px;height:44px;border-radius:12px;font-size:8px}.touch-shop{position:absolute;right:18px;bottom:100px;border-radius:12px!important;width:54px!important;height:38px!important;font-size:9px!important;color:var(--lime)!important}.menu .menu-hint{white-space:nowrap}
