// A recognizable roadside dealership and an outdoor vehicle lineup.
const garageX=27, garageZ=4;
box(24,.5,16,mat(0x515b59),world,[garageX,.1,garageZ+14]);
box(22,8,1,mat(0x283638),world,[garageX,4,garageZ+6]);
